task.en:
What is wrong in the following code?
double x = 3.0;
int* pX = &x;

example.code:
#include <iostream>

int main() {
    int x = 5;
    int y = 6;

    int* pX = &x;
    int* pY = &y;

    // Test 1: Dereferenced assignment (*pX = *pY)
    *pX = *pY;
    std::cout << "After *pX = *pY: x = " << x << ", y = " << y << std::endl;
    std::cout << "pX points to: " << *pX << ", pY points to: " << *pY << std::endl;

    // Reset x and test 2: Pointer assignment (pX = pY)
    x = 100;
    pX = &x;
    pX = pY;
    std::cout << "After pX = pY: *pX = " << *pX << ", *pY = " << *pY << std::endl;

    // Modifying through pX now modifies y, not x
    *pX = 42;
    std::cout << "After *pX = 42: x = " << x << ", y = " << y << std::endl;

    return 0;
}

#include <iostream>

// Using typedef and modern using
typedef int* IntPtr;
using DoublePtr = double*;

int main() {
    // Guaranteeing multiple pointer declarations
    IntPtr a, b;
    int val1 = 10, val2 = 20;
    a = &val1;
    b = &val2;
    std::cout << "IntPtr a: " << *a << ", IntPtr b: " << *b << std::endl;

    // Constant pointer: pointer is fixed, data is mutable
    double radius = 5.0;
    double* const pConstPtr = &radius;
    *pConstPtr = 12.5; // Valid
    std::cout << "Updated radius via constant pointer: " << radius << std::endl;

    // Pointer to const data: data is immutable through pointer, pointer is reassignable
    double length = 30.0;
    const double* pConstData = &radius;
    std::cout << "pConstData points to: " << *pConstData << std::endl;
    pConstData = &length; // Valid reassignment
    std::cout << "pConstData reassigned to length: " << *pConstData << std::endl;

    return 0;
}
